import { UuidV7ValueObject } from '../uuidv7-value-object'

// Always generated by the backend (UUIDv7), never taken from the client: it is the
// opaque key under which the evidence binary lives in blob storage.
export class StorageKey extends UuidV7ValueObject {
  protected static override fieldName = 'Storage key'

  private constructor(value: string) {
    super(value)
  }

  static create(value: string): StorageKey {
    this.ensureIsValidUuidV7(value)
    return new StorageKey(value)
  }
}
